def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    bg = grid[0][0]

    # Create a copy that starts with the input
    output = [[bg] * cols for _ in range(rows)]

    # Copy all non-bg cells from input to output
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                output[r][c] = grid[r][c]

    # For each value appearing >= 2 times, extend diagonally
    value_positions = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != bg:
                if v not in value_positions:
                    value_positions[v] = []
                value_positions[v].append((r, c))

    # For each value with >= 2 positions
    for v, positions in value_positions.items():
        if len(positions) < 2:
            continue

        # Check if they form a diagonal (can be main or anti-diagonal)
        # A line is: r - c = const (main diagonal) or r + c = const (anti-diagonal)
        first_r, first_c = positions[0]
        second_r, second_c = positions[1]

        # Check if diagonal
        main_diag_diff = first_r - first_c
        if second_r - second_c == main_diag_diff:
            diag_type = 'main'
        elif second_r + second_c == first_r + first_c:
            diag_type = 'anti'
        else:
            continue  # Not diagonal, skip

        # For each position, extend in both diagonal directions
        for pr, pc in positions:
            # Direction vectors
            # Main diagonal: dr=dc=+1 or dr=dc=-1
            if diag_type == 'main':
                for dr, dc in [(1, 1), (-1, -1)]:
                    # Extend forward and backward
                    curr_r, curr_c = pr + dr, pc + dc
                    while 0 <= curr_r < rows and 0 <= curr_c < cols:
                        if grid[curr_r][curr_c] != bg:
                            break  # Hit another non-bg cell
                        output[curr_r][curr_c] = v
                        curr_r += dr
                        curr_c += dc
            else:
                for dr, dc in [(1, -1), (-1, 1)]:
                    curr_r, curr_c = pr + dr, pc + dc
                    while 0 <= curr_r < rows and 0 <= curr_c < cols:
                        if grid[curr_r][curr_c] != bg:
                            break
                        output[curr_r][curr_c] = v
                        curr_r += dr
                        curr_c += dc
        # Stop after processing (don't double process)
        break

    return output

