    rows = len(grid)
    cols = len(grid[0])
    bg = grid[0][0]

    output = [[bg] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                output[r][c] = grid[r][c]

    value_positions = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
