                if v not in value_positions:
                    value_positions[v] = []
                value_positions[v].append((r, c))

    for v, positions in value_positions.items():
        if len(positions) < 2:
            continue

        found_diagonal_pairs = []
        for i in range(len(positions)):
            for j in range(i+1, len(positions)):
                r0, c0 = positions[i]
                r1, c1 = positions[j]
                if r0 - c0 == r1 - c1:
